// Lit la reponse de l'IA ; si l'IA echoue, un plan B par regles prend le relais (le workflow ne plante jamais).
const form = $('Formulaire ticket IT').item.json;
const probleme = String(form['Probleme'] || '');
const PRIO = ['Basse', 'Moyenne', 'Haute', 'Critique'];
const CAT = ['Reseau', 'Messagerie', 'Poste de travail', 'Imprimante', 'Securite', 'Compte/Acces', 'Autre'];
let ia = null, source = 'IA';
try {
  const txt = $json.candidates[0].content.parts[0].text;
  ia = JSON.parse(txt.replace(/```json|```/g, '').trim());
} catch (e) { ia = null; }
if (!ia || !PRIO.includes(ia.priorite)) {
  source = 'REGLES (IA indisponible)';
  const p = probleme.toLowerCase();
  const critique = /virus|ransom|rancon|pirat|hack|vol de|fuite|serveur.*(arret|panne|down)|panne generale/.test(p);
  ia = { categorie: 'Autre', priorite: critique ? 'Critique' : 'Moyenne',
         resume: probleme.slice(0, 120), solution_proposee: 'A analyser par un technicien.', escalade: critique };
}
if (!CAT.includes(ia.categorie)) ia.categorie = 'Autre';
const iso = new Date().toISOString().slice(0, 10);
const num = 'TK-' + iso.replace(/-/g, '') + '-' + String(Math.floor(Math.random() * 9000) + 1000);
const escalade = (ia.escalade === true || ia.priorite === 'Critique') ? 'Oui' : 'Non';
return { json: { Numero: num, Date: iso, Demandeur: form['Nom'], Probleme: probleme, Categorie: ia.categorie,
  Priorite: ia.priorite, Resume: ia.resume, SolutionProposee: ia.solution_proposee, Escalade: escalade,
  Source: source, Statut: 'Ouvert' } };
